using Microsoft.EntityFrameworkCore;using Microsoft.AspNetCore.Identity;using BanhangcodeX.Data;using BanhangcodeX.Models;using BanhangcodeX.Services;using Microsoft.AspNetCore.HttpOverrides;
var isRender=string.Equals(Environment.GetEnvironmentVariable("RENDER"),"true",StringComparison.OrdinalIgnoreCase);var b=WebApplication.CreateBuilder(args);if(isRender)b.Services.Configure<ForwardedHeadersOptions>(o=>{o.ForwardedHeaders=ForwardedHeaders.XForwardedProto;o.KnownIPNetworks.Clear();o.KnownProxies.Clear();});var cs=Environment.GetEnvironmentVariable("LIVEORDER_MYSQL")??b.Configuration.GetConnectionString("Default");if(string.IsNullOrWhiteSpace(cs))throw new InvalidOperationException("Configure LIVEORDER_MYSQL.");b.Services.AddDbContext<AppDbContext>(o=>o.UseMySql(cs,ServerVersion.AutoDetect(cs)));b.Services.AddScoped<OrderParser>();b.Services.AddScoped<IPasswordHasher<AppUser>,PasswordHasher<AppUser>>();b.Services.AddControllers();b.Services.AddAuthentication("Cookies").AddCookie("Cookies",o=>{o.Cookie.Name="LiveOrder.Auth";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Strict;o.Cookie.SecurePolicy=CookieSecurePolicy.SameAsRequest;o.ExpireTimeSpan=TimeSpan.FromHours(10);o.Events.OnRedirectToLogin=c=>{c.Response.StatusCode=401;return Task.CompletedTask;};});b.Services.AddAuthorization();b.Services.AddProblemDetails();var app=b.Build();if(isRender)app.UseForwardedHeaders();app.UseExceptionHandler();if(!app.Environment.IsDevelopment())app.UseHsts();app.UseHttpsRedirection();app.UseDefaultFiles();app.UseStaticFiles();app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.MapGet("/health",async(AppDbContext db)=>await db.Database.CanConnectAsync()?Results.Ok(new{status="ok"}):Results.Problem("Database unavailable",statusCode:503));using(var s=app.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<AppDbContext>();await db.Database.MigrateAsync();var pw=Environment.GetEnvironmentVariable("LIVEORDER_ADMIN_PASSWORD");var resetAdmin=string.Equals(Environment.GetEnvironmentVariable("LIVEORDER_RESET_ADMIN_PASSWORD"),"True",StringComparison.OrdinalIgnoreCase);var adminName=Environment.GetEnvironmentVariable("LIVEORDER_ADMIN_USER")??"admin";var existingUser=await db.Users.SingleOrDefaultAsync(u=>u.UserName==adminName);if(existingUser==null){if(string.IsNullOrWhiteSpace(pw)||pw.Length<10)throw new InvalidOperationException("Set LIVEORDER_ADMIN_PASSWORD (10+ chars) for the first Admin account.");var u=new AppUser{UserName=adminName};u.PasswordHash=s.ServiceProvider.GetRequiredService<IPasswordHasher<AppUser>>().HashPassword(u,pw);db.Users.Add(u);await db.SaveChangesAsync();}else if(resetAdmin){if(string.IsNullOrWhiteSpace(pw)||pw.Length<6)throw new InvalidOperationException("Reset password must contain at least 6 characters.");existingUser.PasswordHash=s.ServiceProvider.GetRequiredService<IPasswordHasher<AppUser>>().HashPassword(existingUser,pw);await db.SaveChangesAsync();}if(app.Environment.IsDevelopment()&&!await db.Products.AnyAsync()){db.Products.AddRange(new Product{Code="A001",Name="Cua",Color="Đỏ",Size="3",Price=550000,Stock=30},new Product{Code="A002",Name="Cua",Color="Đen",Size="4",Price=550000,Stock=20});await db.SaveChangesAsync();}}app.Run();


